static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    Densenet121CustomTilingData tiling;

    const gert::StorageShape *x_shape = context->GetInputShape(0);
    const gert::StorageShape *y_shape = context->GetInputShape(1);

    uint32_t n = x_shape->GetOriginShape().GetDimNum() >= 1 ? x_shape->GetOriginShape().GetDim(0) : 1;
    uint32_t c1 = x_shape->GetOriginShape().GetDimNum() >= 2 ? x_shape->GetOriginShape().GetDim(1) : 1;
    uint32_t h  = x_shape->GetOriginShape().GetDimNum() >= 3 ? x_shape->GetOriginShape().GetDim(2) : 1;
    uint32_t w  = x_shape->GetOriginShape().GetDimNum() >= 4 ? x_shape->GetOriginShape().GetDim(3) : 1;

    uint32_t c2 = y_shape->GetOriginShape().GetDimNum() >= 2 ? y_shape->GetOriginShape().GetDim(1) : 1;

    uint32_t xPerN = c1 * h * w;
    uint32_t yPerN = c2 * h * w;

    // 简单设定一个适中的tile长度，按元素计
    const uint32_t TILE_LEN = 4096;

    tiling.set_n(n);
    tiling.set_xPerN(xPerN);
    tiling.set_yPerN(yPerN);
    tiling.set_tileLen(TILE_LEN);

    context->SetBlockDim(1);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

