    uint64_t h  = x_shape->GetDimNum() >= 3 ? x_shape->GetDim(2) : 1;
    uint64_t w  = x_shape->GetDimNum() >= 4 ? x_shape->GetDim(3) : 1;
    uint64_t c2 = y_shape->GetDimNum() >= 2 ? y_shape->GetDim(1) : 1;

